dleplugin.phpinstall:
$c_file = ENGINE_DIR . '/data/peestream.conf.php';
$peestream_config = array();
if( file_exists( $c_file ) ) {
	include( $c_file );
}
$init_secret = bin2hex( random_bytes( 24 ) );
$defaults = array (
	'api_key' => '',
	'player_domain' => 'https://peeplayer.com',
	'api_domain' => 'https://peestream.com',
	'default_folder_id' => '0',
	'responsive' => '1',
	'width' => '100%',
	'height' => '500',
	'aspect_ratio' => '16:9',
	'autoplay' => '0',
	'allow_fullscreen' => '1',
	'xfield_name' => 'peestream',
	'webhook_secret' => $init_secret,
	'auto_create_news' => '0',
	'default_category' => '1',
	'moderate_new_posts' => '1',
);
if( !is_array( $peestream_config ) ) {
	$peestream_config = array();
}
$merged = array_merge( $defaults, $peestream_config );
if( empty( $merged['webhook_secret'] ) || strlen( $merged['webhook_secret'] ) < 16 || $merged['webhook_secret'] === '529c675e950e1f3b3e3d27415b8437d54923b5c21f331241' ) {
	$merged['webhook_secret'] = $init_secret;
}
$content = "<?PHP\n\n\$peestream_config = " . var_export( $merged, true ) . ";\n\n?>";
@file_put_contents( $c_file, $content );
@chmod( $c_file, 0644 );

