	if( empty( $peestream_config['webhook_secret'] ) || strlen( $peestream_config['webhook_secret'] ) < 16 || $peestream_config['webhook_secret'] === '529c675e950e1f3b3e3d27415b8437d54923b5c21f331241' ) {
